@namespace sv_1f4de20a41e34048a493373088ba63be.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var index = i;
        var stepNumber = i + 1;
        var css = GetStepCss(index);
        var isClickable = CompletedSteps.Contains(index) && index != CurrentStep;

        <button class="step @css"
                disabled="@(!isClickable)"
                @onclick="() => OnStepClicked.InvokeAsync(index)"
                aria-current="@(index == CurrentStep ? "step" : null)">
            <span class="step-circle">
                @if (CompletedSteps.Contains(index) && index != CurrentStep)
                {
                    <span class="checkmark">✓</span>
                }
                else
                {
                    @stepNumber
                }
            </span>
            <span class="step-label">@StepNames[index]</span>
        </button>

        @if (i < StepNames.Length - 1)
        {
            <span class="step-connector @(CompletedSteps.Contains(index) ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepCss(int index)
    {
        if (index == CurrentStep) return "active";
        if (CompletedSteps.Contains(index)) return "completed";
        return "future";
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 2rem;
    padding: 1.5rem 1rem;
    flex-wrap: wrap;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border: none;
    cursor: default;
    padding: 0.25rem 0.5rem;
    min-width: 5rem;
}

.step.completed:not(:disabled) {
    cursor: pointer;
}

.step-circle {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    transition: all 0.2s;
}

.step.active .step-circle {
    background: #2563eb;
    color: #fff;
    box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.2);
}

.step.completed .step-circle {
    background: #16a34a;
    color: #fff;
}

.step.future .step-circle {
    background: #e5e7eb;
    color: #9ca3af;
}

.checkmark {
    font-size: 1.1rem;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    line-height: 1.2;
    max-width: 5.5rem;
}

.step.active .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step.completed .step-label {
    color: #16a34a;
}

.step.future .step-label {
    color: #9ca3af;
}

.step-connector {
    flex: 0 0 2rem;
    height: 2px;
    background: #e5e7eb;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #16a34a;
}

.work-entry-card {
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.card-header {
    display: flex;
