+@namespace sv_1f4de20a41e34048a493373088ba63be.Components.Pages.Apply
+
+<nav class="step-indicator" aria-label="Application steps">
+    @for (int i = 0; i < StepNames.Length; i++)
+    {
+        var index = i;
+        var stepNumber = i + 1;
+        var css = GetStepCss(index);
+        var isClickable = CompletedSteps.Contains(index) && index != CurrentStep;
+
+        <button class="step @css"
+                disabled="@(!isClickable)"
+                @onclick="() => OnStepClicked.InvokeAsync(index)"
+                aria-current="@(index == CurrentStep ? "step" : null)">
+            <span class="step-circle">
+                @if (CompletedSteps.Contains(index) && index != CurrentStep)
+                {
+                    <span class="checkmark">✓</span>
+                }
+                else
+                {
+                    @stepNumber
+                }
+            </span>
+            <span class="step-label">@StepNames[index]</span>
+        </button>
+
+        @if (i < StepNames.Length - 1)
+        {
+            <span class="step-connector @(CompletedSteps.Contains(index) ? "completed" : "")"></span>
+        }
+    }
+</nav>
+
+@code {
+    private static readonly string[] StepNames =
+        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];
+
+    [Parameter, EditorRequired] public int CurrentStep { get; set; }
+    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
+    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }
+
+    private string GetStepCss(int index)
+    {
+        if (index == CurrentStep) return "active";
+        if (CompletedSteps.Contains(index)) return "completed";
+        return "future";
+    }
+}
+

