+@namespace sv_1f4de20a41e34048a493373088ba63be.Components.Pages.Apply
+
+<div class="step-content">
+    <h3>Personal Information</h3>
+
+    <EditForm Model="Model" OnValidSubmit="HandleNext">
+        <DataAnnotationsValidator />
+
+        <div class="form-group">
+            <label for="fullName">Full Name</label>
+            <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
+            <ValidationMessage For="() => Model.FullName" />
+        </div>
+
+        <div class="form-group">
+            <label for="email">Email</label>
+            <InputText id="email" @bind-Value="Model.Email" class="form-control" />
+            <ValidationMessage For="() => Model.Email" />
+            @if (!string.IsNullOrEmpty(_emailError))
+            {
+                <div class="validation-message">@_emailError</div>
+            }
+        </div>
+
+        <div class="form-group">
+            <label for="phone">Phone</label>
+            <InputText id="phone" @bind-Value="Model.Phone" class="form-control" />
+            <ValidationMessage For="() => Model.Phone" />
+        </div>
+
+        <div class="form-group">
+            <label for="address">Address</label>
+            <InputTextArea id="address" @bind-Value="Model.Address" class="form-control" rows="2" />
+            <ValidationMessage For="() => Model.Address" />
+        </div>
+
+        <div class="step-actions">
+            <button type="submit" class="btn btn-primary" disabled="@_validating">
+                @if (_validating)
+                {
+                    <span>Validating…</span>
+                }
+                else
+                {
+                    <span>Next →</span>
+                }
+            </button>
+        </div>
+    </EditForm>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
+    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
+    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;
+
+    private bool _validating;
+    private string? _emailError;
+
+    private async Task HandleNext()
+    {
+        _emailError = null;
+        _validating = true;
+
+        try
+        {
+            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
+            if (!isValid)
+            {
+                _emailError = "This email address could not be verified.";
+                return;
+            }
+
+            await OnNext.InvokeAsync();
+        }
+        finally
+        {
+            _validating = false;
+        }
+    }
+}
+

