@namespace sv_1f4de20a41e34048a493373088ba63be.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter below</label>
        <textarea id="coverLetter"
                  class="form-control cover-letter-textarea"
                  maxlength="2000"
                  rows="12"
                  @bind="CurrentValue"
                  @bind:event="oninput"></textarea>
        <div class="char-count @(CurrentValue.Length > 1800 ? "warning" : "")">
            @CurrentValue.Length / 2000 characters
        </div>
    </div>

    <div class="step-actions">
        <button type="button" class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">← Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext"
                disabled="@(string.IsNullOrWhiteSpace(CurrentValue))">
            Next →
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string CurrentValue
    {
        get => CoverLetter;
        set => CoverLetterChanged.InvokeAsync(value);
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

.step-content h3 {
    margin-top: 0;
}

.cover-letter-textarea {
    width: 100%;
    resize: vertical;
    min-height: 200px;
    font-family: inherit;
    padding: 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    box-sizing: border-box;
}

.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

.char-count.warning {
    color: #dc2626;
    font-weight: 600;
}

