.step-content h3 {
    margin-top: 0;
}

.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
    color: #374151;
}

.btn-edit {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-edit:hover {
    color: #1d4ed8;
}

.review-grid {
    display: grid;
    grid-template-columns: 8rem 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-grid dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.875rem;
}

.review-grid dd {
    margin: 0;
    font-size: 0.875rem;
}

.review-work-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-work-entry:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.review-dates {
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

.review-description {
    font-size: 0.85rem;
    color: #4b5563;
    margin: 0.5rem 0 0;
}

.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-reference:last-child {
    border-bottom: none;
}

.review-contact {
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

.review-cover-letter {
    font-size: 0.875rem;
    white-space: pre-wrap;
    margin: 0;
    color: #374151;
}

.btn-submit {
    background: #16a34a;
    border-color: #16a34a;
}

.btn-submit:hover:not(:disabled) {
    background: #15803d;
}

.error-banner {
    background: #fef2f2;
    border: 1px solid #fca5a5;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

.confirmation {
    text-align: center;
    padding: 2rem 1rem;
}

.confirmation-icon {
    width: 4rem;
    height: 4rem;
    background: #16a34a;
    color: #fff;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    margin: 0 auto 1rem;
