.confirmation h3 {
    color: #16a34a;
    margin-bottom: 0.5rem;
}

.application-id {
    font-size: 1.5rem;
    font-weight: 700;
    color: #2563eb;
    margin: 1rem 0;
}

.confirmation-note {
    color: #6b7280;
    font-size: 0.875rem;
}

