@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <EditForm Model="Entries[index]">
        <DataAnnotationsValidator />
        <WorkEntryCard Entry="Entries[index]"
                       Index="index"
                       CanRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    </EditForm>
}

<button type="button" class="btn btn-secondary" @onclick="AddEntry">
    + Add Another Position
</button>

@if (_showErrors)
{
    <div class="validation-message">Please fill in all required fields for each position.</div>
}

<div class="step-actions">
    <button type="button" class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">← Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

arguments.old_str:
    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

arguments.new_str:
    private bool _showErrors;

    private async Task HandleNext()
    {
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(new object());
        var allValid = true;

        foreach (var entry in Entries)
        {
            var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
            if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(
                entry, new System.ComponentModel.DataAnnotations.ValidationContext(entry), results, true))
            {
                allValid = false;
            }
        }

        _showErrors = !allValid;
        if (allValid)
        {
            await OnNext.InvokeAsync();
        }
    }
}

